			(*_stat64)(unsafe.Pointer(pStatBuf)).Fst_atime = time_t(fileTimeToUnixTime(tls, bp+12))
			(*_stat64)(unsafe.Pointer(pStatBuf)).Fst_mtime = time_t(fileTimeToUnixTime(tls, bp+20))
