func testHexChar(tls *libc.TLS, c int8) int32 {
	if int32(c) >= '0' && int32(c) <= '9' {
		return int32(c) - '0'
	} else if int32(c) >= 'a' && int32(c) <= 'f' {
		return int32(c) - 'a' + 10
	} else if int32(c) >= 'A' && int32(c) <= 'F' {
		return int32(c) - 'A' + 10
	}
	return 0
}

