	count = *(*uint32)(unsafe.Pointer(ctx + 20)) >> 3 & uint32(0x3F)

	p = ctx + 28 + uintptr(count)
	*(*uint8)(unsafe.Pointer(libc.PostIncUintptr(&p, 1))) = uint8(0x80)

